--     dependencies keep their dependents unavailable until repaired.
[1650] = "展開「函式綁定」可新增明確的輔助函式別名並選擇其目標。變更別名不會改寫你的 Lua 函式主體。缺少、已停用或無效的相依項目會讓相依於它們的項目在修復前維持無法使用。",
-- 9d60841e English: Check
[1651] = "檢查",
