--     stable.
[1690] = "函式名稱使用字母、數字與底線，並以字母或底線開頭。名稱會作為呼叫它們時所用區域綁定的建議；登錄識別碼保持穩定。",
-- b545dd16 English: This cannot be undone.
[1691] = "此操作無法復原。",
-- f07f87d9 English: Delete this announcement?
[1692] = "刪除此通報？",
